with a as(select * from public.authors where open_library_id=any(array['OL20646A','OL1213378A','OL55234A']::text[]) or id=any(array[32,637,638,887]::bigint[])) select jsonb_build_object('checked_at',clock_timestamp(),'authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'isbn_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789077932018','9789023425939','9789023414988']::text[])),'source_work_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where open_library_id=any(array['OL14877416W','OL15266417W','OL15266456W']::text[])),'title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','works','row',to_jsonb(t))),'[]') from public.works t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['ladywindermereswaaier','verscheurdezebriefikvertelveelteveel','verscheurdezebriefikvertelveelteveeleenbriefwisseling','jevriendschapiswerkelijkonbetaalbaar']::text[])),'edition_title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','editions','row',to_jsonb(t))),'[]') from public.editions t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['ladywindermereswaaier','verscheurdezebriefikvertelveelteveel','verscheurdezebriefikvertelveelteveeleenbriefwisseling','jevriendschapiswerkelijkonbetaalbaar']::text[])),'reserved_test_ranges',jsonb_build_object('works',(select count(*) from public.works where id between 987158001 and 987158999),'editions',(select count(*) from public.editions where id between 987258001 and 987258999),'authors',(select count(*) from public.authors where id between 987358001 and 987358999))) as preflight;
